 $('globalSourceLink').hidden=false;const v=$('globalVariable').value,temp=v==='temperatureC';Object.assign(d,{min:temp?-40:0,max:temp?45:d.accumulated?200:20,raw:true,variable:temp?'temperature':'precipitationRate'});if(d.accumulated)d.levels=[1,5,10,25,50,100,200,400];const idx=globalNearest(d.coords,globalSelectedPoint),val=d.values[idx];$('globalPrimary').textContent=fmt(temp?convertTemp(val):val);$('globalUnit').textContent=d.unit;$('globalKind').textContent=d.kind;$('globalHeading').textContent=d.heading;$('globalValid').textContent=d.valid;$('globalLabel').textContent=d.label;$('globalSource').textContent=d.source;$('globalCaveat').textContent=d.caveat;$('globalSourceLink').href=d.sourceURL;$('globalGrid').textContent='Nearest sampled model point '+d.coords[idx][0].toFixed(2)+'°, '+d.coords[idx][1].toFixed(2)+'°. Global grid; no city-point fitting.';$('globalStatus').textContent=d.kind+' · '+d.valid+' · '+d.coords.length.toLocaleString()+' sampled native grid cells';$('fetchStatus').textContent=d.source;$('legendTitle').textContent=d.label;$('legendMin').textContent=(temp?fmt(convertTemp(d.min)):d.min)+' '+d.unit;$('legendMax').textContent=(temp?fmt(convertTemp(d.max)):d.max)+' '+d.unit;document.querySelector('.map-caption').textContent=d.kind+' · COARSE GLOBAL GRID';$('contourStatus').textContent=(temp?'Isotherms':d.accumulated?'Cumulative precipitation contours':'Constant precipitation-rate contours')+' · '+d.unit+' · interpolation only inside sampled grid cells. No added spatial resolution.';draw();
