function globalNearest(coords,point){let best=Infinity,index=0;coords.forEach((c,i)=>{const delta=((c[1]-point[1]+540)%360)-180,d=(c[0]-point[0])**2+(delta*Math.cos(point[0]*Math.PI/180))**2;if(d<best){best=d;index=i}});return index}
